import React, { useState } from 'react';

const StartProject = () => {
  const [projectName, setProjectName] = useState('');
  const [projectDescription, setProjectDescription] = useState('');
  const [difficulty, setDifficulty] = useState('Beginner');
  const [tags, setTags] = useState('');
  const [error, setError] = useState('');
  const [projects, setProjects] = useState([]);

  const handleSubmit = (e) => {
    e.preventDefault();
    if (!projectName || !projectDescription) {
      setError('Please fill out all required fields.');
      return;
    }
    setError('');

    const newProject = {
      name: projectName,
      description: projectDescription,
      difficulty,
      tags: tags.split(',').map(tag => tag.trim()),
    };

    setProjects([...projects, newProject]);

    // Reset form
    setProjectName('');
    setProjectDescription('');
    setDifficulty('Beginner');
    setTags('');
  };

  return (
    <section style={{ background: '#ccf0f4', minHeight: '100vh', padding: '2rem 0' }}>
      <div
        className="container"
        style={{
          maxWidth: '480px',
          margin: '0 auto',
          padding: '2rem',
          background: '#e8fbe5',
          borderRadius: '12px',
          boxShadow: '0 4px 12px rgba(0,0,0,0.1)',
        }}
      >
        <h2 style={{ textAlign: 'center', marginBottom: '1.5rem' }}>✨ Start a New Project</h2>
        <form onSubmit={handleSubmit}>
          <input
            type="text"
            placeholder="📌 Project Name"
            value={projectName}
            maxLength={50}
            onChange={(e) => setProjectName(e.target.value)}
            style={{ width: '100%', marginBottom: '0.5rem', padding: '0.75rem', borderRadius: '8px' }}
          />
          <small style={{ display: 'block', textAlign: 'right' }}>{projectName.length}/50</small>

          <textarea
            placeholder="📝 Project Description"
            value={projectDescription}
            maxLength={250}
            rows={4}
            onChange={(e) => setProjectDescription(e.target.value)}
            style={{ width: '100%', marginBottom: '0.5rem', padding: '0.75rem', borderRadius: '8px' }}
          />
          <small style={{ display: 'block', textAlign: 'right' }}>{projectDescription.length}/250</small>

          <input
            type="text"
            placeholder="🏷️ Tags (comma-separated)"
            value={tags}
            onChange={(e) => setTags(e.target.value)}
            style={{ width: '100%', marginBottom: '1rem', padding: '0.75rem', borderRadius: '8px' }}
          />

          <select
            value={difficulty}
            onChange={(e) => setDifficulty(e.target.value)}
            style={{ width: '100%', marginBottom: '1rem', padding: '0.75rem', borderRadius: '8px' }}
          >
            <option value="Beginner">🟢 Beginner</option>
            <option value="Intermediate">🟡 Intermediate</option>
            <option value="Advanced">🔴 Advanced</option>
          </select>

          {error && <p style={{ color: 'red', marginBottom: '1rem' }}>{error}</p>}

          <button
            type="submit"
            style={{
              width: '100%',
              background: 'black',
              color: 'white',
              padding: '0.75rem',
              borderRadius: '8px',
              fontWeight: 'bold',
              cursor: 'pointer',
            }}
          >
            🚀 Create Project
          </button>
        </form>
      </div>

      {/* Display created projects */}
      {projects.length > 0 && (
        <div style={{ maxWidth: '720px', margin: '2rem auto', padding: '1rem' }}>
          <h3 style={{ textAlign: 'center' }}>📚 Your Projects</h3>
          {projects.map((proj, idx) => (
            <div
              key={idx}
              style={{
                background: '#fff',
                padding: '1rem',
                borderRadius: '8px',
                marginBottom: '1rem',
                boxShadow: '0 2px 6px rgba(0,0,0,0.1)',
              }}
            >
              <h4>{proj.name}</h4>
              <p>{proj.description}</p>
              <p>
                <strong>Difficulty:</strong> {proj.difficulty}
              </p>
              <div>
                {proj.tags.map((tag, i) => (
                  <span
                    key={i}
                    style={{
                      background: '#e0e7ff',
                      color: '#3730a3',
                      padding: '4px 8px',
                      marginRight: '6px',
                      borderRadius: '12px',
                      fontSize: '0.75rem',
                    }}
                  >
                    #{tag}
                  </span>
                ))}
              </div>
            </div>
          ))}
        </div>
      )}
    </section>
  );
};

export default StartProject;
